  },
  {
    "practice": "Mathematical Modeling",
    "why": "Although the context is real-world, the modeling is already fully specified: the scale factor, material costs, and design are given. The student does not need to identify a problem, select variables, or build a model from scratch. The model is provided, and the student only applies it."
  },
  {
    "practice": "Collaborative Mathematics",
    "why": "The item presents a solo task with no reference to another student’s thinking, dialogue, or work. There is no need to evaluate, build on, or respond to a peer’s idea, so collaboration is not required."
  }
]
}

